WITH enriched AS (SELECT src.id, src.order_id, src.product_id, src.unit_price, p.category, p.launch_date, p.cost FROM order_items src INNER JOIN products p ON src.product_id = p.id) SELECT CASE WHEN cost >= 660 THEN 'LARGE' ELSE 'SMALL' END AS cost_tier, SIZE(COLLECT_SET(category)) AS num_categories, COUNT(DISTINCT product_id) AS distinct_product_ids, SIZE(COLLECT_SET(category)) AS num_categories_2 FROM enriched GROUP BY cost_tier HAVING num_categories_2 > 1 ORDER BY num_categories DESC NULLS FIRST;
